USE asan_bis;
SET NAMES utf8mb4;
START TRANSACTION;

-- 운수사

-- 번호판 블록
DELETE FROM company_plate_range;

-- 차종

-- 아이콘 규칙
DELETE FROM vehicle_icon_rule;

-- 차량 등록
DELETE FROM vehicle_registration WHERE company_code IN ('BOSEONG', 'SAMAN', 'SAECHEONAN', 'ASAN', 'ONYANG');
-- BOSEONG (155대, 원문 보성여객 차량목록.txt)
-- SAMAN (128대, 원문 삼안여객 차량목록.txt)
